// The alignment-guide references (alignment guides spec, "The boxes" and
// "The reference cache"): the world box of every movable object, built at
// document-change rate and read by the solver.
//
// A movable object is a root instance (a unit, or a symbol with no unit:
// a bar counter) or a unit generated by a root group. A box is the
// instance's definition box through its world transform, as the unit
// index and the placement ghost both compute it: direct leaves only,
// ATTRIBs (a unit's label) excluded.
import 'dart:typed_data';

import 'package:jet_cad_2d/jet_cad_2d.dart';
import 'package:jet_cad_2d_kit/jet_cad_2d_kit.dart'
    show SymbolBox, UnitComponent, UnitKinds, boxOfLeaves;

import '../units/unit_index.dart';
import 'guide_solver.dart';

/// The world AABB of [box] (definition space) through [t]: the min and max
/// of its four transformed corners, written to [out] as
/// `[minX, minY, maxX, maxY]`. A placement ghost's box (spec, The boxes).
void worldBoxOf(SymbolBox box, Transform2 t, Float64List out) =>
    _worldBox(box.left, box.front, box.right, box.back, t, out);

void _worldBox(
    double x0, double y0, double x1, double y1, Transform2 t, Float64List out) {
  var minX = double.infinity, minY = double.infinity;
  var maxX = double.negativeInfinity, maxY = double.negativeInfinity;
  void corner(double x, double y) {
    final wx = t.a * x + t.c * y + t.e;
    final wy = t.b * x + t.d * y + t.f;
    if (wx < minX) minX = wx;
    if (wx > maxX) maxX = wx;
    if (wy < minY) minY = wy;
    if (wy > maxY) maxY = wy;
  }

  corner(x0, y0);
  corner(x1, y0);
  corner(x1, y1);
  corner(x0, y1);
  out[0] = minX;
  out[1] = minY;
  out[2] = maxX;
  out[3] = maxY;
}

/// The references of one document, rebuilt lazily (spec, The reference
/// cache): when [units]' index is a new object, or the document's
/// `commands.stateId` or its tables' revision moved since the last read.
/// `UnitIndexCache` already folds in the locks and the catalog.
final class GuideReferenceCache {
  /// [units] is read lazily: the session creates its `UnitIndexCache` after
  /// the tools (P-2).
  GuideReferenceCache(this.document, {required UnitIndexCache Function() units})
      : _units = units;

  final DraftDocument document;
  final UnitIndexCache Function() _units;

  GuideReferences? _references;
  Map<Handle, int> _slotOf = const {};
  UnitIndex? _index;
  int? _state;
  int? _revision;

  /// The references, ascending by handle; the identical object while
  /// nothing moved.
  GuideReferences get current {
    final index = _units().current;
    final state = document.commands.stateId;
    final revision = document.tables.mutationRevision;
    final cached = _references;
    if (cached != null &&
        identical(index, _index) &&
        state == _state &&
        revision == _revision) {
      return cached;
    }
    _index = index;
    _state = state;
    _revision = revision;
    return _references = _build(index);
  }

  /// Writes the union of [handles]' boxes into [out] (minX, minY, maxX,
  /// maxY); false when none of them has a box (a leaf, a hidden object, a
  /// seat). May allocate: drag start only.
  bool unionOf(Iterable<Handle> handles, Float64List out) {
    final refs = current;
    var any = false;
    var minX = double.infinity, minY = double.infinity;
    var maxX = double.negativeInfinity, maxY = double.negativeInfinity;
    for (final h in handles) {
      final i = _slotOf[h];
      if (i == null) continue;
      any = true;
      final b = refs.boxes;
      if (b[4 * i] < minX) minX = b[4 * i];
      if (b[4 * i + 1] < minY) minY = b[4 * i + 1];
      if (b[4 * i + 2] > maxX) maxX = b[4 * i + 2];
      if (b[4 * i + 3] > maxY) maxY = b[4 * i + 3];
    }
    if (!any) return false;
    out[0] = minX;
    out[1] = minY;
    out[2] = maxX;
    out[3] = maxY;
    return true;
  }

  GuideReferences _build(UnitIndex index) {
    final tree = document.tree;
    final entities = document.entities;
    final root = tree.root;
    final layers = document.tables.layers;
    // One bucketing pass, only when a symbol with no unit exists: the
    // definitions' leaves by owner, ATTRIBs skipped.
    Map<Handle, List<int>>? leaves;
    final boxes = <Handle, (double, double, double, double)?>{};
    (double, double, double, double)? boxOfDefinition(Handle definition) {
      if (boxes.containsKey(definition)) return boxes[definition];
      final byOwner = leaves ??= () {
        final m = <Handle, List<int>>{};
        for (final slot in entities.liveSlots) {
          if (entities.kindAt(slot) == EntityKind.attrib) continue;
          (m[entities.ownerAt(slot)] ??= []).add(slot);
        }
        return m;
      }();
      final b = boxOfLeaves([
        for (final s in [...?byOwner[definition]])
          (entities.kindAt(s), document.geometry.read(entities.geomIndexAt(s))),
      ]);
      return boxes[definition] =
          b == null ? null : (b.left, b.front, b.right, b.back);
    }

    final handles = <Handle>[];
    final flat = <double>[];
    final scratch = Float64List(4);
    void add(
        Handle h, double x0, double y0, double x1, double y1, Transform2 t) {
      final det = t.determinant;
      if (det == 0 || !det.isFinite) return;
      if (!(x0 <= x1 && y0 <= y1)) return;
      _worldBox(x0, y0, x1, y1, t, scratch);
      for (final v in scratch) {
        if (!v.isFinite) return;
      }
      handles.add(h);
      flat.addAll(scratch);
    }

    // `tree.nodes` is ascending by handle (its contract), so the references
    // are too.
    for (final node in tree.nodes) {
      if (node is! InstanceNode || !node.visible) continue;
      final unit = index[node.handle];
      if (unit != null) {
        if (unit.kind == UnitKinds.seat || !unit.visible) continue;
        final owner = unit.owner;
        if (owner != null && !(tree[owner]?.visible ?? false)) continue;
        final b = unit.box;
        if (b.isEmpty) continue;
        add(node.handle, b.minX, b.minY, b.maxX, b.maxY, unit.toWorld);
        continue;
      }
      if (node.parent != root) continue;
      if (tree.definition(node.definition) == null) continue;
      if (document.components.get<UnitComponent>(node.definition) != null) {
        continue;
      }
      if (!(layers[node.layer]?.visible ?? true)) continue;
      final b = boxOfDefinition(node.definition);
      if (b == null) continue;
      add(node.handle, b.$1, b.$2, b.$3, b.$4, node.transform);
    }
    _slotOf = {for (var i = 0; i < handles.length; i++) handles[i]: i};
    return GuideReferences(Float64List.fromList(flat), handles);
  }
}
